arguments.command:
cd /tmp/agentteams-complex-20260913-run3/candidate/workspace && mkdir -p .verify && ( node --input-type=module > .verify/server.log 2>&1 <<'EOF'
import {readFile} from 'node:fs/promises';
import {startServer} from './src/server.mjs';

const catalog = JSON.parse(await readFile('./fixtures/catalog.json', 'utf8'));
const stock = JSON.parse(await readFile('./fixtures/stock.json', 'utf8'));

const {url, close} = await startServer({catalog, stock, dataFile: './data/orders.json', port: 3000});
console.log(`listening on ${url}`);
EOF
) & SERVER_PID=$!
sleep 0.6
for i in $(seq 1 50); do curl -s -o /dev/null http://127.0.0.1:3000/health && break; sleep 0.1; done
echo "=== documented server start (stdout) ===" && cat .verify/server.log
echo "=== GET /health ===" && curl -s -w '\nHTTP %{http_code}\n' http://127.0.0.1:3000/health
kill $SERVER_PID 2>/dev/null; wait $SERVER_PID 2>/dev/null; rm -rf .verify data
echo "=== release.json ===" && node -e "const fs=require('node:fs');const r=JSON.parse(fs.readFileSync('reports/release.json','utf8'));console.log('valid JSON, ready='+r.ready, 'summary_nonempty='+(typeof r.summary==='string'&&r.summary.trim().length>0), 'summary_chars='+r.summary.length)"
echo "=== reports/ ===" && ls -la reports
echo "=== tree (excluding .agent-teams) ===" && find . -path ./.agent-teams -prune -o -type f -print | sort
echo "=== import specifiers across src/bin/tests ===" && grep -rhoE "from '[^']+" src bin tests | sort -u
echo "=== node_modules ===" && (ls -d node_modules 2>&1 || true)
echo "=== protected sha256 (baseline prefixes) ===" && sha256sum SPEC.md package.json tests/public-contract.test.mjs fixtures/*.json | awk '{print substr($1,1,8), $2}'
echo "=== FINAL npm test ===" && npm test 2>&1 | tail -12; echo "npm_test_exit=${PIPESTATUS[0]}"
